SELECT Scuola.AnnoS, Go.Sede, [Prof.Cognome] & " " & [Prof.Nome] AS NominativoProf, [Go.Cognome] & " " & [Go.Nome] AS NominativoUc, Go.tel, Go.mail, Go.cel, Materia.Stejemo, Materia.Materia, Scuola.Razred, Sum(Scuola.Ore) AS Ore, Podruzica.Dove, Scuola.DataI, Scuola.DataF, Scuola.Posk, IIf([DataF] Is Not Null,Month([DataF]-[DataI]),Month(Now()-[DataI])) AS Mese, Scuola.DataF, Scuola.DataI2
FROM ((Prof RIGHT JOIN ([Go] INNER JOIN Scuola ON Go.IdP=Scuola.IdP) ON Prof.IdPr=Scuola.IdPr) LEFT JOIN Materia ON Scuola.IdM=Materia.IdM) LEFT JOIN Podruzica ON Scuola.IdD=Podruzica.IdD
GROUP BY Scuola.AnnoS, Go.Sede, [Prof.Cognome] & " " & [Prof.Nome], [Go.Cognome] & " " & [Go.Nome], Go.tel, Go.mail, Go.cel, Materia.Stejemo, Materia.Materia, Scuola.Razred, Podruzica.Dove, Scuola.DataI, Scuola.DataF, Scuola.Posk, IIf([DataF] Is Not Null,Month([DataF]-[DataI]),Month(Now()-[DataI])), Scuola.DataF, Scuola.DataI2
HAVING (((Scuola.AnnoS) Like [Inserire Anno Scolastico]) AND ((Materia.Stejemo) Not Like "st-*") AND ((Scuola.DataF) Is Null) AND ((Scuola.Posk)=0)) OR (((Scuola.AnnoS) Like [Inserire Anno Scolastico]) AND ((Materia.Stejemo) Not Like "st-*") AND ((Scuola.Posk)=0) AND (Not (Scuola.DataI2) Is Null));
